const screens=[...document.querySelectorAll(".screen")];const stageButtons=[...document.querySelectorAll(".stage-button")];const total=screens.length;const storageKey=document.body.dataset.ovaId+"-completed";let current=0;let completed=new Set();try{const saved=JSON.parse(localStorage.getItem(storageKey)||"[]");completed=new Set(saved.filter(n=>Number.isInteger(n)&&n>=0&&n<total))}catch{}const progressLabel=document.querySelector("#progress-label");const progressFill=document.querySelector("#progress-fill");const progressTrack=document.querySelector(".progress-track");const completion=document.querySelector("#completion");function full(){return completed.size===total&&screens.every((_,i)=>completed.has(i))}function update(){const percent=Math.round(completed.size/total*100);progressLabel.textContent=`Avance validado: ${percent} % · ${completed.size} de ${total} etapas`;progressFill.style.width=percent+"%";progressTrack.setAttribute("aria-valuenow",String(percent));stageButtons.forEach((button,i)=>button.classList.toggle("is-complete",completed.has(i)));completion.hidden=!full()}function show(index,focus=true){current=(index+total)%total;screens.forEach((screen,i)=>{screen.hidden=i!==current;screen.classList.toggle("is-active",i===current)});stageButtons.forEach((button,i)=>{button.classList.toggle("is-current",i===current);button.setAttribute("aria-current",i===current?"step":"false")});document.querySelector("#position").textContent=`Etapa ${current+1} de ${total}`;if(focus){screens[current].querySelector("h2").focus?.({preventScroll:true});screens[current].scrollIntoView({behavior:"smooth",block:"start"})}}stageButtons.forEach(button=>button.addEventListener("click",()=>show(Number(button.dataset.go))));document.querySelector("#previous").addEventListener("click",()=>show(current-1));document.querySelector("#next").addEventListener("click",()=>show(current+1));document.querySelectorAll(".activity").forEach((form,index)=>form.addEventListener("submit",event=>{event.preventDefault();const selected=form.querySelector("input:checked");const feedback=form.querySelector(".feedback");if(!selected){feedback.textContent="Selecciona una respuesta antes de comprobar.";feedback.className="feedback error";return}if(Number(selected.value)===Number(form.dataset.correct)){completed.add(index);try{localStorage.setItem(storageKey,JSON.stringify([...completed]))}catch{}feedback.textContent="Correcto. "+feedback.dataset.success;feedback.className="feedback success";update()}else{feedback.textContent="Aún no. Relee el contexto, revisa la relación entre evidencia y conclusión e inténtalo otra vez.";feedback.className="feedback error"}}));document.querySelector("#restart").addEventListener("click",()=>{if(!confirm("¿Deseas borrar el avance y reiniciar esta OVA?"))return;completed.clear();try{localStorage.removeItem(storageKey)}catch{}document.querySelectorAll(".activity").forEach(form=>{form.reset();const feedback=form.querySelector(".feedback");feedback.textContent="";feedback.className="feedback"});document.querySelector("#student-name").value="";update();show(0)});document.querySelector("#download-badge").addEventListener("click",()=>{if(!full())return;const name=(document.querySelector("#student-name").value.trim()||"Estudiante").replace(/[<>&"']/g,"");const title=document.title.replace(/^OVA \d+ — /,"");const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="1200"><rect width="1200" height="1200" rx="70" fill="#f7fbfc"/><rect width="1200" height="250" fill="#44388a"/><circle cx="600" cy="500" r="240" fill="#44388a" stroke="#d4af37" stroke-width="34"/><g opacity=".58" fill="none" stroke="#f4d76b" stroke-width="13"><path d="M590 315c-60-43-130 0-120 67-68 22-77 106-22 142-23 70 52 124 111 82 38 69 144 43 146-37 70-20 81-113 18-148 17-68-62-118-119-77-7-12-9-18-14-29Z"/><path d="M590 315v290M470 380h75v60h45M440 490h95v55h55M710 380h-75v60h-45M760 495h-100v50h-70"/></g><text x="600" y="455" text-anchor="middle" font-family="Arial" font-weight="700" font-size="55" fill="#fff7cf">INSIGNIA</text><text x="600" y="570" text-anchor="middle" font-family="Arial" font-weight="800" font-size="120" fill="white">100%</text><text x="600" y="650" text-anchor="middle" font-family="Arial" font-weight="700" font-size="32" fill="#fff7cf">OVA COMPLETADO</text><text x="600" y="840" text-anchor="middle" font-family="Arial" font-weight="800" font-size="45" fill="#26233f">${title}</text><text x="600" y="925" text-anchor="middle" font-family="Arial" font-size="38" fill="#44388a">Otorgada a ${name}</text><text x="600" y="1000" text-anchor="middle" font-family="Arial" font-size="28" fill="#5a5672">Universidad de Cartagena · 100 % validado</text></svg>`;const blob=new Blob([svg],{type:"image/svg+xml"});const link=document.createElement("a");link.href=URL.createObjectURL(blob);link.download=document.body.dataset.ovaId+"-insignia.svg";link.click();setTimeout(()=>URL.revokeObjectURL(link.href),1000)});update();show(0,false);